"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["10373"],{45716(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.documento_nao_enviado_como_edital","status":422,"titulo":"Somente um documento enviado como edital pode ser o documento do edital"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.documento_nao_enviado_como_edital","requisitos":["UNI-REQ-0019","UNI-REQ-0154"],"oQueAconteceu":["O documento indicado como documento do edital existe, \xe9 do processo e est\xe1 confirmado, mas\\nfoi enviado com outra finalidade: como anexo do edital ou como documento de ato. A\\nfinalidade \xe9 declarada no in\xedcio do envio e n\xe3o muda. S\xf3 o documento enviado como\\n`DOCUMENTO_DO_EDITAL` pode ser o PDF principal do edital de abertura ou de retifica\xe7\xe3o. A\\nconfer\xeancia \xe9 a mesma na publica\xe7\xe3o, na retifica\xe7\xe3o e no fechamento da retifica\xe7\xe3o, e\\nacontece antes de qualquer grava\xe7\xe3o."],"comoResolver":["Indique como documento do edital um documento enviado com a finalidade `DOCUMENTO_DO_EDITAL`.\\nSe o arquivo certo foi enviado com outra finalidade, inicie um novo envio dele como\\ndocumento do edital, confirme e use o novo identificador. O que foi enviado como anexo\\ncontinua v\xe1lido como anexo: veja\\n[`anexo_do_edital.finalidade_incompativel`](/erros/uniplus.selecao.anexo_do_edital.finalidade_incompativel)."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o do processo seletivo","Fechamento de retifica\xe7\xe3o"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);